import { useEffect, useState } from 'react';
import { PackageMinus, RotateCcw } from 'lucide-react';
import Alert from '../../../components/ui/Alert.jsx';
import Button from '../../../components/ui/Button.jsx';
import Drawer from '../../../components/ui/Drawer.jsx';
import Input from '../../../components/ui/Input.jsx';
import { createAdjustment, createReturn } from '../../../services/adjustments.service.js';
import { formatDate, formatQuantity } from '../../../utils/format.js';

const actions = [
  { value: 'write_off', label: 'Write off as expired' },
    { value: 'return_to_supplier', label: 'Return to supplier' },
      { value: 'quarantined', label: 'Quarantine' },
        { value: 'blocked', label: 'Block from use' },
          { value: 'destroyed', label: 'Destroy' }
          ];

          const defaultReason = (action, batch) => {
            if (!batch) {
                return '';
                  }
                    switch (action) {
                        case 'write_off':
                              return `Expired stock write-off (${batch.batchNumber})`;
                                  case 'return_to_supplier':
                                        return `Return to supplier (${batch.batchNumber})`;
                                            case 'quarantined':
                                                  return `Quarantined pending inspection (${batch.batchNumber})`;
                                                      case 'blocked':
                                                            return `Blocked from use (${batch.batchNumber})`;
                                                                default:
                                                                      return `Destroyed stock (${batch.batchNumber})`;
                                                                        }
                                                                        };

                                                                        export default function BatchActionDrawer({ open, onClose, batch, onDone }) {
                                                                          const [action, setAction] = useState('write_off');
                                                                            const [quantity, setQuantity] = useState('');
                                                                              const [reason, setReason] = useState('');
                                                                                const [error, setError] = useState('');
                                                                                  const [saving, setSaving] = useState(false);

                                                                                    useEffect(() => {
                                                                                        if (!open || !batch) {
                                                                                              return;
                                                                                                  }
                                                                                                      setAction('write_off');
                                                                                                          setQuantity(String(batch.quantity));
                                                                                                              setReason(defaultReason('write_off', batch));
                                                                                                                  setError('');
                                                                                                                    }, [open, batch]);

                                                                                                                      const changeAction = (value) => {
                                                                                                                          setAction(value);
                                                                                                                              setReason(defaultReason(value, batch));
                                                                                                                                  setError('');
                                                                                                                                    };

                                                                                                                                      const handleSubmit = async (event) => {
                                                                                                                                          event.preventDefault();

                                                                                                                                              const amount = Number(quantity);
                                                                                                                                                  if (!(amount > 0)) {
                                                                                                                                                        setError('Enter a quantity greater than zero.');
                                                                                                                                                              return;
                                                                                                                                                                  }
                                                                                                                                                                      if (amount > Number(batch?.quantity || 0)) {
                                                                                                                                                                            setError('The quantity cannot be more than the batch holds.');
                                                                                                                                                                                  return;
                                                                                                                                                                                      }
                                                                                                                                                                                          if (reason.trim().length < 3) {
                                                                                                                                                                                                setError('A reason of at least 3 characters is required.');
                                                                                                                                                                                                      return;
                                                                                                                                                                                                          }

                                                                                                                                                                                                              setSaving(true);
                                                                                                                                                                                                                  setError('');
                                                                                                                                                                                                                      try {
                                                                                                                                                                                                                            if (action === 'write_off') {
                                                                                                                                                                                                                                    const result = await createAdjustment({
                                                                                                                                                                                                                                              drugId: batch.drugId,
                                                                                                                                                                                                                                                        batchId: batch.id,
                                                                                                                                                                                                                                                                  adjustmentType: 'expiry_writeoff',
                                                                                                                                                                                                                                                                            quantity: -amount,
                                                                                                                                                                                                                                                                                      reason: reason.trim()
                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                      onDone(
                                                                                                                                                                                                                                                                                                                result.requiresApproval
                                                                                                                                                                                                                                                                                                                            ? 'Write-off submitted and waiting for an administrator.'
                                                                                                                                                                                                                                                                                                                                        : 'Write-off applied and stock updated.'
                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                      } else {
                                                                                                                                                                                                                                                                                                                                                              const result = await createReturn({
                                                                                                                                                                                                                                                                                                                                                                        reason: reason.trim(),
                                                                                                                                                                                                                                                                                                                                                                                  items: [{ batchId: batch.id, quantity: amount, disposition: action }]
                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                  onDone(
                                                                                                                                                                                                                                                                                                                                                                                                            `Return request ${result.returnRequest.requestNumber} created and waiting for approval.`
                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                              } catch (submitError) {
                                                                                                                                                                                                                                                                                                                                                                                                                                    setError(submitError.message || 'The batch action could not be saved.');
                                                                                                                                                                                                                                                                                                                                                                                                                                        } finally {
                                                                                                                                                                                                                                                                                                                                                                                                                                              setSaving(false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Drawer
                                                                                                                                                                                                                                                                                                                                                                                                                                                                open={open}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onClose={onClose}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            title="Deal with this batch"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  subtitle={batch ? `${batch.drugName} · ${batch.batchNumber}` : undefined}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {batch ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <form onSubmit={handleSubmit} className="space-y-4" noValidate>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {error ? <Alert tone="error">{error}</Alert> : null}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="rounded-xl border border-sand-200 bg-sand-50 px-3 py-2.5 text-xs text-primary-600">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  On hand: <span className="font-semibold">{formatQuantity(batch.quantity)}</span>{' '}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {batch.unitOfMeasure}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p className="mt-0.5">Expires {formatDate(batch.expiryDate)}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <label className="field-label" htmlFor="batch-action">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      What should happen
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <select
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            id="batch-action"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          value={action}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onChange={(event) => changeAction(event.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      className="field"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {actions.map((option) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <option key={option.value} value={option.value}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {option.label}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </select>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            label={`Quantity (max ${formatQuantity(batch.quantity)})`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        name="batchActionQuantity"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    type="number"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                min="0"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            step="any"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        value={quantity}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onChange={(event) => setQuantity(event.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              />

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <label className="field-label" htmlFor="batch-action-reason">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Reason
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <textarea
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        id="batch-action-reason"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      value={reason}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onChange={(event) => setReason(event.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  rows={3}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                className="field resize-none"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {action === 'write_off' ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p className="text-xs text-primary-500">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Large write-offs go to an administrator before stock changes.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p className="text-xs text-primary-500">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Returns always need approval before the batch status changes.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="flex flex-col gap-2 border-t border-sand-200 pt-4 sm:flex-row-reverse">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Button type="submit" loading={saving} className="sm:flex-1">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {action === 'write_off' ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <PackageMinus className="h-4 w-4" aria-hidden="true" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <RotateCcw className="h-4 w-4" aria-hidden="true" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {saving ? 'Saving' : action === 'write_off' ? 'Submit write-off' : 'Submit return'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </Button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Button type="button" variant="outline" onClick={onClose} className="sm:flex-1">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Cancel
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </Button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) : null}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </Drawer>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }